package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Working-storage
var WsEofFlag string          // PIC X len=1 = "N"
var WsC decimal.Decimal       // PIC S9(3)V99 len=5 = 0
var WsFreeze int64            // PIC 99 len=2 = 0
var WsCount int64             // PIC 99 len=2 = 0
var WsFEd string              // PIC ZZ9.9 len=5
var WsCEd string              // PIC -ZZ9.99 len=7

var curRec TempRec
var inputLines []string
var inputIdx int

func main() {
	MainPara()
}

func MainPara() {
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0
	WsFEd = ""
	WsCEd = ""

	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
			os.Exit(1)
		}
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			inputLines = append(inputLines, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		f.Close()
	}
	inputIdx = 0

	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE TEMP-FILE

	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	countStr := formatPIC99(WsCount)
	freezeStr := formatPIC99(WsFreeze)
	fmt.Println("READINGS: " + countStr + " BELOW ZERO: " + freezeStr)
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	recStr := line
	if len(recStr) < 8 {
		recStr = recStr + strings.Repeat(" ", 8-len(recStr))
	} else if len(recStr) > 8 {
		recStr = recStr[:8]
	}
	sensor := recStr[0:4]
	fStr := recStr[4:8]
	curRec.TcSensor = sensor
	curRec.TcF = parseTCF(fStr)
}

func ProcessPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := curRec.TcF.Sub(decimal.NewFromInt(32))
	mult := diff.Mul(decimal.NewFromInt(5))
	raw := mult.Div(decimal.NewFromInt(9))
	rounded := roundHalfAway(raw, 2)
	WsC = fitDecimal(rounded, 3, 2)

	if WsC.Sign() < 0 {
		WsFreeze++
		WsFreeze = fitInt99(WsFreeze)
	}
	WsCount++
	WsCount = fitInt99(WsCount)

	WsFEd = formatEdited(curRec.TcF, "ZZ9.9")
	WsCEd = formatEdited(WsC, "-ZZ9.99")

	line := curRec.TcSensor + " " + WsFEd + "F " + WsCEd + "C"
	fmt.Println(line)

	ReadPara()
}

// helpers

func parseTCF(s string) decimal.Decimal {
	var digits strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits.WriteRune(ch)
		}
	}
	dStr := digits.String()
	if dStr == "" {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(dStr, 10, 64)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return decimal.New(n, -1)
}

func roundHalfAway(d decimal.Decimal, places int32) decimal.Decimal {
	shifted := d.Shift(places)
	intPart := shifted.Truncate(0)
	frac := shifted.Sub(intPart)
	half := decimal.NewFromInt(5).Shift(-1) // 0.5
	if frac.Abs().Cmp(half) >= 0 {
		if shifted.Sign() >= 0 {
			intPart = intPart.Add(decimal.NewFromInt(1))
		} else {
			intPart = intPart.Sub(decimal.NewFromInt(1))
		}
	}
	return intPart.Shift(-places)
}

func fitDecimal(v decimal.Decimal, intDigits, scale int) decimal.Decimal {
	if v.IsZero() {
		return decimal.NewFromInt(0)
	}
	sign := v.Sign()
	abs := v.Abs()
	scaled := abs.Shift(int32(scale)).Truncate(0)
	totalDigits := intDigits + scale
	mod := decimal.New(1, int32(totalDigits))
	rem := scaled.Mod(mod)
	if rem.IsZero() {
		return decimal.NewFromInt(0)
	}
	res := rem.Shift(int32(-scale))
	if sign < 0 {
		res = res.Neg()
	}
	return res
}

func fitInt99(v int64) int64 {
	if v >= 0 {
		return v % 100
	}
	return v % 100
}

func formatPIC99(v int64) string {
	// PIC 99 zero padded width 2, overflow already truncated
	if v < 0 {
		return fmt.Sprintf("%02d", v)
	}
	return fmt.Sprintf("%02d", v%100)
}

func formatEdited(value decimal.Decimal, picture string) string {
	hasSign := false
	pic := picture
	signChar := ' '
	isNeg := value.Sign() < 0 && !value.IsZero()
	if len(pic) > 0 && pic[0] == '-' {
		hasSign = true
		pic = pic[1:]
		if isNeg {
			signChar = '-'
		} else {
			signChar = ' '
		}
	}
	absVal := value.Abs()

	dotIdx := strings.Index(pic, ".")
	var leftPart, rightPart string
	if dotIdx >= 0 {
		leftPart = pic[:dotIdx]
		rightPart = pic[dotIdx+1:]
	} else {
		leftPart = pic
		rightPart = ""
	}
	intPlaceholders := 0
	for _, ch := range leftPart {
		if ch == 'Z' || ch == '9' || ch == ',' {
			intPlaceholders++
		}
	}
	fracPlaceholders := len(rightPart)

	intPartDec := absVal.Truncate(0)
	intStrRaw := intPartDec.String()
	if strings.HasPrefix(intStrRaw, "-") {
		intStrRaw = intStrRaw[1:]
	}
	if idx := strings.Index(intStrRaw, "."); idx >= 0 {
		intStrRaw = intStrRaw[:idx]
	}
	if len(intStrRaw) > intPlaceholders {
		intStrRaw = intStrRaw[len(intStrRaw)-intPlaceholders:]
	}
	paddedInt := intStrRaw
	if len(paddedInt) < intPlaceholders {
		paddedInt = strings.Repeat("0", intPlaceholders-len(paddedInt)) + paddedInt
	}

	var leftOut []rune
	phIdx := 0
	seenNonZero := false
	for _, ch := range leftPart {
		if ch == ',' {
			if seenNonZero {
				leftOut = append(leftOut, ',')
			} else {
				leftOut = append(leftOut, ' ')
			}
		} else if ch == 'Z' || ch == '9' {
			digit := paddedInt[phIdx]
			phIdx++
			if ch == 'Z' {
				if !seenNonZero && digit == '0' {
					leftOut = append(leftOut, ' ')
				} else {
					leftOut = append(leftOut, rune(digit))
					if digit != '0' {
						seenNonZero = true
					}
				}
			} else { // '9'
				leftOut = append(leftOut, rune(digit))
				if digit != '0' {
					seenNonZero = true
				}
			}
		}
	}

	var fracStr string
	if fracPlaceholders > 0 {
		fracDec := absVal.Sub(intPartDec)
		scaledFrac := fracDec.Shift(int32(fracPlaceholders)).Truncate(0)
		fracIntStr := scaledFrac.String()
		fracIntStr = strings.TrimPrefix(fracIntStr, "-")
		if idx := strings.Index(fracIntStr, "."); idx >= 0 {
			fracIntStr = fracIntStr[:idx]
		}
		if len(fracIntStr) < fracPlaceholders {
			fracStr = strings.Repeat("0", fracPlaceholders-len(fracIntStr)) + fracIntStr
		} else if len(fracIntStr) > fracPlaceholders {
			fracStr = fracIntStr[len(fracIntStr)-fracPlaceholders:]
		} else {
			fracStr = fracIntStr
		}
	}

	var result string
	if hasSign {
		result = string(signChar) + string(leftOut)
	} else {
		result = string(leftOut)
	}
	if fracPlaceholders > 0 {
		result = result + "." + fracStr
	}
	return result
}
